public class StatusLineReaderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("a normal status line", 200, StatusLineReader.statusCode("HTTP/1.1 200 OK"));
            check("a code with no reason phrase", 301,
                    StatusLineReader.statusCode("HTTP/1.0 301"));
            check("a non-numeric code is malformed", -1,
                    StatusLineReader.statusCode("HTTP/1.1 OK 200"));
            check("a request line is not a status line", -1,
                    StatusLineReader.statusCode("GET / HTTP/1.1"));
            check("null is malformed", -1, StatusLineReader.statusCode(null));

            check("a multi-word reason phrase", "Not Found",
                    StatusLineReader.reasonPhrase("HTTP/1.1 404 Not Found"));
            check("a missing reason phrase", "",
                    StatusLineReader.reasonPhrase("HTTP/1.0 301"));
            check("a malformed line has no reason phrase", "",
                    StatusLineReader.reasonPhrase("nonsense"));

            check("category 204", "success", StatusLineReader.category(204));
            check("category 302", "redirect", StatusLineReader.category(302));
            check("category 404", "client error", StatusLineReader.category(404));
            check("category 503", "server error", StatusLineReader.category(503));
            check("category 100", "informational", StatusLineReader.category(100));
            check("category -1", "unknown", StatusLineReader.category(-1));
            check("category 600", "unknown", StatusLineReader.category(600));

            check("503 is retryable", true, StatusLineReader.isRetryable(503));
            check("429 is retryable", true, StatusLineReader.isRetryable(429));
            check("404 is not retryable", false, StatusLineReader.isRetryable(404));
            check("501 is not retryable", false, StatusLineReader.isRetryable(501));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

