/**
 * TASK: Read an HTTP status line and classify the code.
 *
 * A status line looks like "HTTP/1.1 404 Not Found": a version, a three-digit
 * code, and an optional reason phrase that may contain spaces.
 *
 * statusCode(line): the code as an int, or -1 when the line is malformed --
 *   it does not start with "HTTP/", it has fewer than two space-separated
 *   parts, or the second part is not a number.
 *     "HTTP/1.1 200 OK"        -> 200
 *     "HTTP/1.0 301"           -> 301   (no reason phrase is still valid)
 *     "HTTP/1.1 OK 200"        -> -1
 *     "GET / HTTP/1.1" or null -> -1
 *
 * reasonPhrase(line): everything after the code, or "" when there is none or
 *   the line is malformed.
 *     "HTTP/1.1 404 Not Found" -> "Not Found"
 *     "HTTP/1.0 301"           -> ""
 *
 * category(code): "informational" 100-199, "success" 200-299, "redirect"
 *   300-399, "client error" 400-499, "server error" 500-599, "unknown" for
 *   anything else (including -1).
 *
 * isRetryable(code): true only for 408, 429, 500, 502, 503 and 504.
 */
public class StatusLineReader {

    public static int statusCode(String line) {
        if (line == null || !line.startsWith("HTTP/")) {
            return -1;
        }
        String[] parts = line.split(" ", 3);
        if (parts.length < 2) {
            return -1;
        }
        try {
            return Integer.parseInt(parts[1]);
        } catch (NumberFormatException e) {
            return -1;
        }
    }

    public static String reasonPhrase(String line) {
        if (statusCode(line) < 0) {
            return "";
        }
        String[] parts = line.split(" ", 3);
        return parts.length < 3 ? "" : parts[2];
    }

    public static String category(int code) {
        if (code >= 100 && code <= 199) {
            return "informational";
        }
        if (code >= 200 && code <= 299) {
            return "success";
        }
        if (code >= 300 && code <= 399) {
            return "redirect";
        }
        if (code >= 400 && code <= 499) {
            return "client error";
        }
        if (code >= 500 && code <= 599) {
            return "server error";
        }
        return "unknown";
    }

    public static boolean isRetryable(int code) {
        return code == 408 || code == 429 || code == 500
                || code == 502 || code == 503 || code == 504;
    }
}
